def _get_custom_confusion_dict(path):
    """
    取自定义困惑集
    :param path:
    :return: dict, {variant: origin}, eg: {"交通先行": "交通限行"}
    """
    confusion = {}
    if path and os.path.exists(path):
        with open(path, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                if line.startswith('#'):
                    continue
                terms = line.split()
                if len(terms) < 2:
                    continue
                wrong = terms[0]
                right = terms[1]
                confusion[wrong] = right
    return confusion
